% Given data
t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];

dt = t(2) - t(1);

% Hybrid integration
I_38 = 3*dt/8 * ...
    (k(1) + 3*k(2) + 3*k(3) + k(4));

I_trap = dt/2 * (k(4) + k(5));

I = I_38 + I_trap;

figure; %[output:4f0d1ae7]
hold on; %[output:4f0d1ae7]

%%\ Simpson's 3/8 region [0,3]

% Fit cubic polynomial through first 4 points
p = polyfit(t(1:4), k(1:4), 3);

% Generate smooth curve
x1 = linspace(0, 3, 150);
y1 = polyval(p, x1);

% Shade area under cubic curve
patch([x1 fliplr(x1)], ... %[output:4f0d1ae7]
    [zeros(size(x1)) fliplr(y1)], ... %[output:4f0d1ae7]
    [0.65 0.82 1.0], ... %[output:4f0d1ae7]
    'FaceAlpha', 0.4, ... %[output:4f0d1ae7]
    'EdgeColor', 'none', ... %[output:4f0d1ae7]
    'HandleVisibility', 'off'); %[output:4f0d1ae7]

% Plot cubic interpolation
plot(x1, y1, 'b-', ... %[output:4f0d1ae7]
    'LineWidth', 2, ... %[output:4f0d1ae7]
    'DisplayName', "Cubic interpolation (Simpson's 3/8)"); %[output:4f0d1ae7]

%%\ Trapezoidal region [3,4]

% Shade trapezoidal area
patch([3 4 4 3], ... %[output:4f0d1ae7]
    [0 0 k(5) k(4)], ... %[output:4f0d1ae7]
    [0.65 0.82 1.0], ... %[output:4f0d1ae7]
    'FaceAlpha', 0.4, ... %[output:4f0d1ae7]
    'EdgeColor', 'none', ... %[output:4f0d1ae7]
    'HandleVisibility', 'off'); %[output:4f0d1ae7]

% Plot straight-line interpolation
plot(t(4:5), k(4:5), 'g-', ... %[output:4f0d1ae7]
    'LineWidth', 2, ... %[output:4f0d1ae7]
    'DisplayName', 'Linear interpolation (Trapezoidal)'); %[output:4f0d1ae7]

%%\ Given data points
plot(t, k, 'ro', ... %[output:4f0d1ae7]
    'MarkerFaceColor', 'r', ... %[output:4f0d1ae7]
    'MarkerSize', 7, ... %[output:4f0d1ae7]
    'DisplayName', 'Given data'); %[output:4f0d1ae7]

% Vertical lines at data points
for i = 1:length(t)
    plot([t(i) t(i)], [0 k(i)], ... %[output:4f0d1ae7]
        'k--', 'LineWidth', 0.8, ... %[output:4f0d1ae7]
        'HandleVisibility', 'off'); %[output:4f0d1ae7]
end

%%\ Formatting
xlabel(' t (s)', 'FontSize', 12); %[output:4f0d1ae7]
ylabel(' k (W/(m K))', ... %[output:4f0d1ae7]
    'FontSize', 12); %[output:4f0d1ae7]

title(sprintf('Hybrid Simpson''s 3/8 and Trapezoidal Rule (I = %.4f)', I)); %[output:4f0d1ae7]

legend('Location', 'southeast'); %[output:4f0d1ae7]
grid on; %[output:4f0d1ae7]
box on; %[output:4f0d1ae7]

xlim([0 4]); %[output:4f0d1ae7]
ylim([0 0.5]); %[output:4f0d1ae7]
xticks(0:1:4); %[output:4f0d1ae7]

set(gca, 'FontSize', 11); %[output:4f0d1ae7]
hold off; %[output:4f0d1ae7]

%%\ Display results
fprintf('Simpson 3/8 integral = %.5f\n', I_38); %[output:65b01f92]
fprintf('Trapezoidal integral = %.5f\n', I_trap); %[output:4d79d4ab]
fprintf('Total integral       = %.5f\n', I); %[output:5d41458a]

% Export for Overleaf after confirming the plot works
 exportgraphics(gcf, 's38-tr.pdf', ... %[output:group:643ee87f] %[output:4f0d1ae7]
     'ContentType', 'vector'); %[output:group:643ee87f] %[output:4f0d1ae7]


